package com.sable;

import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;

/**
 * The panel's two sections: the clan overview, and every rank in the clan under it.
 */
final class AccountView
{
	/** Pictures for the panel. Either may be missing while it loads, and a missing picture is left out. */
	interface Icons
	{
		/** One of the game's own sprites. */
		Icon sprite(int id);

		/** A small picture from an address (the clan's rank emoji). */
		Icon image(String url);

		/** An item's own picture, such as the Collection Log book. */
		Icon item(int id);

		/** The picture of an item found by its name; missing until it has been looked up. */
		Icon itemNamed(String name);
	}

	/** The game's own sprite the points tile uses. Number from RuneLite's SpriteID. */
	static final class Sprites
	{
		static final int CLAN = 2307;

		private Sprites()
		{
		}
	}

	private AccountView()
	{
	}

	private static Icon sprite(Icons icons, int id)
	{
		return icons == null ? null : icons.sprite(id);
	}

	private static String number(long n)
	{
		return String.format(Locale.US, "%,d", n);
	}

	/** Which ladder the main account is on, in words. Empty when the bot has not said. */
	static String ladderText(ClanInfo clan)
	{
		if (clan == null || clan.ladderOn == null)
		{
			return "";
		}

		if (!clan.inClan)
		{
			return "Your main account is not in the clan.";
		}

		switch (clan.ladderOn)
		{
			case "pvm":
				return "Your main account is on the PvM ladder.";
			case "loyalty":
				return "Your main account is on the Loyalty ladder.";
			case "charter":
				return "Charter: outside both ladders.";
			case "manual":
				return "";
			default:
				return "Your main account has no rank in game yet.";
		}
	}

	private static String ladderName(String to)
	{
		return "pvm".equals(to) ? "PvM" : "Loyalty";
	}

	/** A button for each ladder the member could move to, or a line saying a move is already waiting. */
	private static JComponent switcher(ClanInfo c, Consumer<String> onSwitch, String message)
	{
		JPanel p = Ui.column();

		if (c.ladderPending != null)
		{
			p.add(Ui.note("A move to " + c.ladderPending + " is waiting for staff to set it in game."));
		}

		// Only somebody on a ladder, or on Charter, has one to change.
		boolean hasLadder = "pvm".equals(c.ladderOn) || "loyalty".equals(c.ladderOn) || "charter".equals(c.ladderOn);

		// Charter sits outside both ladders, so it always shows both ways in, the one without a rank earned yet greyed out.
		if (onSwitch != null && "charter".equals(c.ladderOn) && c.inClan && c.ladderPending == null)
		{
			for (String to : new String[] {"pvm", "loyalty"})
			{
				ClanInfo.Target target = null;

				for (ClanInfo.Target t : c.ladderTargets)
				{
					if (to.equals(t.to))
					{
						target = t;
					}
				}

				Ui.gap(p, 6);
				JButton b = new JButton("Change to " + ladderName(to) + " ladder");
				b.setFocusable(false);
				b.setAlignmentX(JComponent.LEFT_ALIGNMENT);
				b.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, 28));

				if (target == null)
				{
					b.setEnabled(false);
					p.add(b);
					Ui.gap(p, 2);
					p.add(Ui.note("You have not earned a " + ladderName(to) + " rank yet."));
				}
				else
				{
					final String go = target.to;
					b.setToolTipText("Asks staff to move you to the " + ladderName(go) + " ladder as " + target.rankName);
					b.addActionListener(e -> onSwitch.accept(go));
					p.add(b);
					Ui.gap(p, 2);
					p.add(Ui.note("Moves you to the " + ladderName(go) + " ladder as " + target.rankName + ". Staff set it in game; the bot never does."));
				}
			}
		}
		else if (onSwitch != null && hasLadder && c.inClan && c.ladderPending == null)
		{
			if (c.ladderTargets.isEmpty())
			{
				Ui.gap(p, 6);
				JButton none = new JButton("Change ladder");
				none.setFocusable(false);
				none.setEnabled(false);
				none.setAlignmentX(JComponent.LEFT_ALIGNMENT);
				none.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, 28));
				p.add(none);
				Ui.gap(p, 2);
				p.add(Ui.note("You have not earned a rank on the other ladder yet."));
			}

			for (ClanInfo.Target t : c.ladderTargets)
			{
				Ui.gap(p, 6);
				// One other ladder is just "Change ladder"; Charter can go either way, so each says where.
				JButton b = new JButton(c.ladderTargets.size() == 1 ? "Change ladder" : "Change ladder to " + ladderName(t.to));
				b.setFocusable(false);
				b.setAlignmentX(JComponent.LEFT_ALIGNMENT);
				b.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, 28));
				b.setToolTipText("Asks staff to move you to the " + ladderName(t.to) + " ladder as " + t.rankName);
				b.addActionListener(e -> onSwitch.accept(t.to));
				p.add(b);
				Ui.gap(p, 2);
				p.add(Ui.note("Moves you to the " + ladderName(t.to) + " ladder as " + t.rankName + ". Staff set it in game; the bot never does."));
			}
		}

		if (message != null && !message.isEmpty())
		{
			Ui.gap(p, 4);
			p.add(Ui.label(message, Ui.small(), Ui.GOLD));
		}

		return p;
	}

	private static JPanel progress(Icons icons, ClanInfo c, String title, String gameRank, long value, long from, long at, String next, long left, String unit)
	{
		JPanel p = Ui.column();
		Icon icon = icons == null ? null : icons.image(c.rankIcon(gameRank));

		if (next == null)
		{
			p.add(new Ui.Progress(title, "Top of the ladder", 1, icon));
		}
		else
		{
			double f = at > from ? (value - from) / (double) (at - from) : 0;
			p.add(new Ui.Progress(title, number(left) + " " + unit + " to " + next, f, icon));
		}

		return p;
	}

	/** Drops waiting on the member, each with its picture and a way to the Discord message that asks. Nothing at all when there are none. */
	static JPanel attention(ClanInfo c, Icons icons, Consumer<String> onOpen, long now)
	{
		JPanel p = Ui.column();

		if (c == null || c.pending.isEmpty())
		{
			return p;
		}

		p.add(Ui.heading("Needs attention"));
		Ui.gap(p, 6);

		for (ClanInfo.Pending d : c.pending)
		{
			p.add(new Ui.Row(d.item, icons == null ? null : icons.itemNamed(d.item)));
			p.add(Ui.note(left(d.until, now) + " to say how you ran it. " + number(d.points) + " points now, " + number(d.full) + " if you were alone or with the clan."));
		}

		if (c.dmUrl != null && onOpen != null)
		{
			Ui.gap(p, 4);
			JButton open = new JButton("Open in Discord");
			open.setAlignmentX(JComponent.LEFT_ALIGNMENT);
			open.addActionListener(e -> onOpen.accept(c.dmUrl));
			p.add(open);
		}

		return p;
	}

	/** How long is left, in the words a person would use. */
	static String left(long until, long now)
	{
		long minutes = Math.max(0, (until - now) / 60_000);

		return minutes >= 60 ? (minutes / 60) + " h left" : minutes + " min left";
	}

	/** Every rank in the clan, open. */
	static JPanel ranks(ClanInfo c, Icons icons)
	{
		return ranks(c, icons, true, null, null);
	}

	static JPanel ranks(ClanInfo c, Icons icons, boolean open, Runnable onToggle)
	{
		return ranks(c, icons, open, onToggle, null);
	}

	/**
	 * Every rank in the clan, one line each: the picture, the name and what earns it.
	 *
	 * The heading opens and closes it, so the panel stays short until somebody wants the list.
	 * The ranks the member holds are picked out in gold.
	 */
	static JPanel ranks(ClanInfo c, Icons icons, boolean open, Runnable onToggle, String liveRank)
	{
		JPanel p = Ui.column();
		p.add(Ui.toggle("All ranks", open, onToggle));

		if (!open)
		{
			return p;
		}

		Ui.gap(p, 6);

		if (c == null || c.ranks.isEmpty())
		{
			p.add(Ui.note("The clan's ranks are not loaded yet."));

			return p;
		}

		String group = null;

		for (ClanInfo.RankRow r : c.ranks)
		{
			if (!r.group.equals(group))
			{
				if (group != null)
				{
					Ui.gap(p, 8);
				}

				p.add(Ui.label(r.group, Ui.small(), Ui.MUTED));
				Ui.gap(p, 2);
				group = r.group;
			}

			// The ranks that are yours: the two ladder ranks, and whatever the game says this character holds (staff, Charter, Echo).
			boolean mine = r.name.equals(c.pvmRank) || r.name.equals(c.loyaltyRank) || (liveRank != null && !r.game.isEmpty() && rankKey(r.game).equals(rankKey(liveRank)) && !isLadder(r.group));

			Ui.Line line = new Ui.Line(r.name, shorten(r.how), icons == null ? null : icons.image(c.rankIcon(r.game)), mine ? Ui.GOLD : Ui.TEXT, Ui.MUTED, false);
			p.add(mine ? line.marked() : line);
		}

		return p;
	}

	private static String rankKey(String rank)
	{
		return rank == null ? "" : rank.toLowerCase(Locale.ROOT).replaceAll("[^a-z]", "");
	}

	private static boolean isLadder(String group)
	{
		return "Loyalty".equals(group) || "PvM".equals(group);
	}

	/** "30 days in the clan" and "500 clan points" as "30 days" and "500 pts", and the longer sentences as a few words, so a rank fits on one line. */
	static String shorten(String how)
	{
		switch (how)
		{
			case "Runs the place.":
				return "Staff";
			case "Here in the first week. Never given again.":
				return "First week only";
			case "A second account. Ranks go on your main.":
				return "Second account";
			case "Won boss of the week.":
				return "Boss of the week";
			case "Won skill of the week.":
				return "Skill of the week";
			default:
				return how.replace(" days in the clan", " days").replace(" clan points", " pts");
		}
	}

	/** The member's last few awards, newest first, each with the points and how long ago. Nothing at all when there are none. */
	static JPanel recent(ClanInfo c, Icons icons, long now)
	{
		return recent(c, icons, now, null);
	}

	/** The same, with each row that has a Discord post opening it when clicked. */
	static JPanel recent(ClanInfo c, Icons icons, long now, Consumer<String> onOpen)
	{
		JPanel p = Ui.column();

		if (c == null || c.recent.isEmpty())
		{
			return p;
		}

		p.add(Ui.heading("Recent points"));
		Ui.gap(p, 4);

		for (ClanInfo.Recent r : c.recent)
		{
			Ui.Line line = new Ui.Line(r.what, (r.points > 0 ? "+" : "") + number(r.points) + "  " + ago(r.at, now), icons == null ? null : icons.itemNamed(r.what), Ui.TEXT, Ui.MUTED, false);
			boolean link = onOpen != null && r.url != null;
			String hint = link ? "Click to open the post in Discord" : null;
			line.setToolTipText(r.detail.isEmpty() ? hint : (hint == null ? r.detail : r.detail + " \u00B7 " + hint));

			if (link)
			{
				line.clickable(() -> onOpen.accept(r.url));
			}

			p.add(line);
		}

		return p;
	}

	/** How long ago, in the words a person would use. */
	static String ago(long at, long now)
	{
		long minutes = Math.max(0, (now - at) / 60_000);

		if (minutes < 60)
		{
			return minutes + "m";
		}

		long hours = minutes / 60;

		return hours < 24 ? hours + "h" : (hours / 24) + "d";
	}

	/** The quick links the clan has set, as buttons. Nothing at all when none is. */
	static JPanel links(ClanInfo c, Consumer<String> onOpen)
	{
		JPanel p = Ui.column();

		if (c == null || onOpen == null)
		{
			return p;
		}

		String[][] all = {
			{"Discord invite", c.linkInvite},
			{"Events", c.linkEvents},
			{"Announcements", c.linkAnnouncements},
			{"Leaderboard", c.linkLeaderboard},
		};

		JPanel grid = new JPanel(new java.awt.GridLayout(0, 2, 4, 4));
		grid.setOpaque(false);
		grid.setAlignmentX(JComponent.LEFT_ALIGNMENT);

		int shown = 0;

		for (String[] link : all)
		{
			if (link[1] == null || link[1].isEmpty())
			{
				continue;
			}

			JButton b = new JButton(link[0]);
			b.setFocusable(false);
			b.setFont(Ui.small());
			b.setMargin(new java.awt.Insets(2, 2, 2, 2));
			b.addActionListener(e -> onOpen.accept(link[1]));
			grid.add(b);
			shown++;
		}

		if (shown == 0)
		{
			return p;
		}

		p.add(Ui.heading("Links"));
		Ui.gap(p, 4);
		p.add(grid);

		return p;
	}

	/** The clan overview: the character's rank in game, then the main account's points and progress. */
	static JPanel clan(ClanInfo c, String liveRank, Icons icons)
	{
		return clan(c, liveRank, icons, null, null);
	}

	/** The same, with the button that moves the member to the other ladder, and the line that says how it went. */
	static JPanel clan(ClanInfo c, String liveRank, Icons icons, Consumer<String> onSwitch, String message)
	{
		JPanel p = Ui.column();
		// Only the rank belongs to the character that is logged in, straight from the game.
		p.add(Ui.heading("This character"));
		Ui.gap(p, 6);

		Icon rankIcon = c == null || icons == null ? null : icons.image(c.rankIcon(liveRank));
		p.add(new Ui.Row(liveRank == null ? "Not in the clan" : liveRank, rankIcon));
		Ui.gap(p, 2);
		p.add(Ui.note("Its rank in the clan. Nothing else here changes with the character you log in as."));

		// Everything else belongs to the member, whichever account they are on.
		p.add(Ui.separator());
		p.add(Ui.heading("Your clan profile"));
		Ui.gap(p, 4);

		if (c == null)
		{
			p.add(Ui.note("Clan points and rank progress are not loaded yet."));

			return p;
		}

		p.add(Ui.note(c.accounts.isEmpty()
			? "These are your points and progress, whichever character you log in as."
			: "These are your points and progress, whichever character you log in as. Linked accounts: " + String.join(", ", c.accounts) + "."));
		Ui.gap(p, 8);

		// The number members look for first: larger, in gold, with the same space above and below.
		p.add(new Ui.Line("Clan points", number(c.points), null, Ui.TEXT, Ui.GOLD, true).big());
		Ui.gap(p, 8);

		p.add(progress(icons, c, "PvM \u00B7 " + (c.pvmRank == null ? "none yet" : c.pvmRank), c.pvmGame, c.points, c.pvmFrom, c.pvmAt, c.pvmNext, c.pvmLeft, "pts"));

		if (c.days != null)
		{
			Ui.gap(p, 6);
			p.add(progress(icons, c, "Loyalty \u00B7 " + (c.loyaltyRank == null ? "none yet" : c.loyaltyRank), c.loyaltyGame, c.days, c.loyaltyFrom, c.loyaltyAt, c.loyaltyNext, c.loyaltyLeft, "days"));
		}

		// The way to the other ladder, and a line only when there is something to say about it.
		String ladder = ladderText(c);

		if (!ladder.isEmpty())
		{
			Ui.gap(p, 8);
			p.add(Ui.note(ladder));
		}

		p.add(switcher(c, onSwitch, message));

		return p;
	}
}

package com.sable;

import com.google.gson.JsonObject;

/** The request bodies that are not an activity. Plain gson, so they test without the client. */
final class Bodies
{
	private Bodies()
	{
	}

	/** "This key's player is logged in as this name." Nothing else rides along. */
	static JsonObject hello(String rsn)
	{
		JsonObject body = new JsonObject();
		body.addProperty("type", "hello");
		body.addProperty("rsn", rsn);

		return body;
	}
}

package com.sable;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What the game's own chat lines mean.
 *
 * Every pattern here is RuneLite's: the kill count and personal best ones are
 * ChatCommandsPlugin's, the collection log, pet, combat task and quest ones are
 * ScreenshotPlugin's, and the diary and combat task ones are the same lines
 * Dink matches. They are copied, not reworded, because the only way to be
 * wrong about a game message is to have written it from memory.
 *
 * No RuneLite types in here on purpose, so all of it can be tested with plain
 * strings.
 */
final class ChatParser
{
	private ChatParser()
	{
	}

	// ChatCommandsPlugin
	static final String TEAM_SIZES = "(?<teamsize>\\d+(?:\\+|-\\d+)? players?|Solo)";

	static final Pattern KILLCOUNT = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?"
			+ "(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?"
			+ "(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");

	private static final String PB_PREFIX =
		"(?i)(?:(?:Fight |Lap |Challenge |Corrupted challenge )?duration:|Subdued in|"
			+ "(?<!total )completion time:|The Fractured Archive: Total completion time:) ";

	static final Pattern NEW_PB = Pattern.compile(
		PB_PREFIX + "(?:<col=[0-9a-f]{6}>|@.+?@)(?<pb>[0-9:]+(?:\\.[0-9]+)?)</col> \\(new personal best\\)");

	static final Pattern KILL_DURATION = Pattern.compile(
		PB_PREFIX + "(?:<col=[0-9a-f]{6}>|@.+?@)[0-9:.]+</col>\\. Personal best: (?:<col=ff0000>|@.+?@)?"
			+ "(?<pb>[0-9:]+(?:\\.[0-9]+)?)");

	static final Pattern RAIDS_PB = Pattern.compile(
		"<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>" + TEAM_SIZES
			+ "</col> Duration:</col> <col=ff0000>(?<pb>[0-9:]+(?:\\.[0-9]+)?)</col> \\(new personal best\\)</col>");

	static final Pattern RAIDS_DURATION = Pattern.compile(
		"<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>" + TEAM_SIZES
			+ "</col> Duration:</col> <col=ff0000>[0-9:.]+</col> Personal best: </col><col=ff0000>"
			+ "(?<pb>[0-9:]+(?:\\.[0-9]+)?)</col>");

	// ChatCommandsPlugin: COLLECTION_LOG_ITEM_PATTERN
	static final Pattern COLLECTION_LOG = Pattern.compile("New item added to your collection log: (.*)");

	// ScreenshotPlugin
	static final String[] PET_MESSAGES = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};

	static final Pattern QUEST_PATTERN_1 = Pattern.compile(
		".+?ve\\.*? (?<verb>been|rebuilt|.+?ed)? ?(?:the )?'?(?<quest>.+?)'?(?: [Qq]uest)?[!.]?$");

	static final Pattern QUEST_PATTERN_2 = Pattern.compile(
		"'?(?<quest>.+?)'?(?: [Qq]uest)? (?<verb>[a-z]\\w+?ed)?(?: f.*?)?[!.]?$");

	// Dink: DiaryNotifier and CombatTaskNotifier
	static final Pattern DIARY = Pattern.compile(
		"Congratulations! You have completed all of the (?<difficulty>.+) tasks in the (?<area>.+) area");

	static final Pattern COMBAT_TASK = Pattern.compile(
		"Congratulations, you've completed an? (?<tier>\\w+) combat task: (?<task>.+)\\.");

	private static final Pattern TASK_POINTS = Pattern.compile("\\s+\\(\\d+ points?\\)$");

	// Words a kill count or time line always has. Used only to notice a line that
	// looks like one but matched nothing, because Jagex reworded it.
	private static final Pattern LOOKS_LIKE_KILL = Pattern.compile(
		"(?i)(duration|personal best|kill count|completion count|success count|completion time)");

	/** A kill count line: which boss, and the count. */
	static final class Kill
	{
		final String boss;
		final int kc;

		Kill(String boss, int kc)
		{
			this.boss = boss;
			this.kc = kc;
		}
	}

	/** A time line: the best time it names, whether it is new, and the team size if the line says. */
	static final class Time
	{
		final long timeMs;
		final boolean precise;
		final boolean isNew;
		final int teamSize; // -1 when the line does not say

		Time(long timeMs, boolean precise, boolean isNew, int teamSize)
		{
			this.timeMs = timeMs;
			this.precise = precise;
			this.isNew = isNew;
			this.teamSize = teamSize;
		}
	}

	/** A diary or combat task: the tier, and the area or the task. */
	static final class Named
	{
		final String tier;
		final String what;

		Named(String tier, String what)
		{
			this.tier = tier;
			this.what = what;
		}
	}

	/** True for a line that reads like a kill count or time, whether or not a pattern took it. */
	static boolean looksLikeKillLine(String plain)
	{
		return LOOKS_LIKE_KILL.matcher(plain).find();
	}

	static Kill kill(String message)
	{
		Matcher m = KILLCOUNT.matcher(message);

		if (!m.find())
		{
			return null;
		}

		String pre = m.group("pre") == null ? "" : m.group("pre");
		String post = m.group("post") == null ? "" : m.group("post");

		// Laps, harvests and ticket totals are not fights.
		boolean fight = post.contains("kill") || post.contains("completion") || post.contains("success")
			|| pre.startsWith("completed") || pre.startsWith("subdued");

		if (!fight)
		{
			return null;
		}

		try
		{
			return new Kill(boss(m.group("boss")), Integer.parseInt(m.group("kc").replace(",", "")));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * The boss as the clan reads it.
	 *
	 * Colons are dropped, as RuneLite's own config does, so "Theatre of Blood: Hard Mode"
	 * and "Theatre of Blood Hard Mode" are one name.
	 */
	static String boss(String raw)
	{
		return raw.replace(":", "").replaceAll("\\s+", " ").trim();
	}

	static Time time(String message)
	{
		Matcher m = RAIDS_PB.matcher(message);

		if (m.find())
		{
			return time(m, true, teamSize(m.group("teamsize")));
		}

		m = RAIDS_DURATION.matcher(message);

		if (m.find())
		{
			return time(m, false, teamSize(m.group("teamsize")));
		}

		m = NEW_PB.matcher(message);

		if (m.find())
		{
			return time(m, true, -1);
		}

		m = KILL_DURATION.matcher(message);

		if (m.find())
		{
			return time(m, false, -1);
		}

		return null;
	}

	private static Time time(Matcher m, boolean isNew, int teamSize)
	{
		String pb = m.group("pb");

		return new Time(toMillis(pb), pb.contains("."), isNew, teamSize);
	}

	/** "Solo" is 1; "3 players" is 3; "8+ players" and "11-15 players" are read as their lower number. */
	static int teamSize(String label)
	{
		if (label == null)
		{
			return -1;
		}

		if (label.equalsIgnoreCase("Solo"))
		{
			return 1;
		}

		Matcher m = Pattern.compile("^\\d+").matcher(label);

		return m.find() ? Integer.parseInt(m.group()) : -1;
	}

	/** "17:42.60" or "1:02:03.40" or "59.4", to milliseconds. */
	static long toMillis(String text)
	{
		String[] parts = text.split(":");
		double seconds = 0;

		for (String part : parts)
		{
			seconds = seconds * 60 + Double.parseDouble(part);
		}

		return Math.round(seconds * 1000);
	}

	static String collectionLog(String plain)
	{
		Matcher m = COLLECTION_LOG.matcher(plain);

		return m.find() ? m.group(1).trim() : null;
	}

	static boolean pet(String plain)
	{
		for (String p : PET_MESSAGES)
		{
			if (plain.contains(p))
			{
				return true;
			}
		}

		return false;
	}

	static Named diary(String plain)
	{
		Matcher m = DIARY.matcher(plain);

		return m.find() ? new Named(capital(m.group("difficulty")), m.group("area").trim()) : null;
	}

	static Named combatTask(String plain)
	{
		Matcher m = COMBAT_TASK.matcher(plain);

		if (!m.find())
		{
			return null;
		}

		return new Named(capital(m.group("tier")), TASK_POINTS.matcher(m.group("task")).replaceAll("").trim());
	}

	/** The quest name from the quest scroll's title, which RuneLite reads with these two patterns in turn. */
	static String quest(String plain)
	{
		Matcher m = QUEST_PATTERN_1.matcher(plain);

		if (m.matches())
		{
			return m.group("quest");
		}

		m = QUEST_PATTERN_2.matcher(plain);

		return m.matches() ? m.group("quest") : null;
	}

	private static String capital(String s)
	{
		String t = s.trim().toLowerCase();

		return t.isEmpty() ? t : Character.toUpperCase(t.charAt(0)) + t.substring(1);
	}
}

package com.sable;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.HashMap;
import java.util.Map;

/** What the bot says about a member that the plugin cannot know itself: clan points, rank progress and the clan's rank pictures. */
final class ClanInfo
{
	long points;
	long monthPoints;
	String pvmRank;
	String pvmGame;
	String pvmNext;
	long pvmLeft;
	long pvmFrom;
	long pvmAt;
	Integer days;
	String loyaltyRank;
	String loyaltyGame;
	String loyaltyNext;
	long loyaltyLeft;
	long loyaltyFrom;
	long loyaltyAt;

	// What the clan announces a drop from. Until the bot says, a guess.
	long dropMin = 500_000;

	// RuneProfile's achievement diary and combat task totals, for when the game's own panel has not been seen. 0 when not known.
	int diariesDone;
	int diariesTotal;
	int tasksDone;
	int tasksTotal;

	/** A ladder the member could move to, and the rank it would put them on. */
	static final class Target
	{
		final String to;
		final String rankName;

		Target(String to, String rankName)
		{
			this.to = to;
			this.rankName = rankName;
		}
	}

	// Which ladder the main account is on (pvm, loyalty, charter, manual or none), whether it is in the clan, and where it could go.
	boolean inClan = true;
	String ladderOn;
	String ladderPending;
	final java.util.List<Target> ladderTargets = new java.util.ArrayList<>();

	// The picture for lines from Discord in game chat: an emoji called discord, or the server's icon, as an address on Discord's image host.
	String chatIcon;

	/** One rank in the clan: the group it is listed under, its name, the game's name for it, and how it is earned. */
	static final class RankRow
	{
		final String group;
		final String name;
		final String game;
		final String how;

		RankRow(String group, String name, String game, String how)
		{
			this.group = group == null ? "" : group;
			this.name = name == null ? "" : name;
			this.game = game;
			this.how = how == null ? "" : how;
		}
	}

	/** A drop that still waits for the member to say how they ran it: what it was, the half paid now, the full amount, and when the question lapses. */
	static final class Pending
	{
		final String item;
		final long points;
		final long full;
		final long until;

		Pending(String item, long points, long full, long until)
		{
			this.item = item == null ? "a drop" : item;
			this.points = points;
			this.full = full;
			this.until = until;
		}
	}

	/** One award from the member's last few: what it was for, the points, and when. */
	static final class Recent
	{
		final String what;
		final long points;
		final long at;
		// Where it came from and its code, shown when the pointer rests on the row.
		final String detail;
		// The Discord post the points came from, or null.
		final String url;

		Recent(String what, long points, long at, String detail, String url)
		{
			this.what = what == null ? "Points" : what;
			this.points = points;
			this.at = at;
			this.detail = detail == null ? "" : detail;
			this.url = url == null || url.isEmpty() ? null : url;
		}
	}

	// The member's last few awards, newest first.
	final java.util.List<Recent> recent = new java.util.ArrayList<>();

	// True when the key belongs to somebody else's accounts: the bot then sends only their names, nothing to show.
	boolean mismatch;

	// The accounts the member has linked, main first. Points and progress count all of them.
	final java.util.List<String> accounts = new java.util.ArrayList<>();

	// Where the quick links go. Any of them may be missing when the clan has not set it.
	String linkInvite;
	String linkEvents;
	String linkAnnouncements;
	String linkLeaderboard;

	// Drops waiting on the member, and the address of the Discord message that asks.
	final java.util.List<Pending> pending = new java.util.ArrayList<>();
	String dmUrl;

	// Every rank, in the order the clan lists them.
	final java.util.List<RankRow> ranks = new java.util.ArrayList<>();

	// Whether the bot counts this key's owner as clan staff, who keep the Wise Old Man group in step with the game.
	boolean staff;

	// Keyed by the game's name for a rank, with only letters and lower case.
	final Map<String, String> rankIcons = new HashMap<>();

	private static String key(String rank)
	{
		return rank == null ? "" : rank.toLowerCase().replaceAll("[^a-z]", "");
	}

	/** The picture address for an in-game rank such as "Owner" or "Squire", or null. */
	String rankIcon(String gameRank)
	{
		return rankIcons.get(key(gameRank));
	}

	/** Reads the bot's /me answer. Missing pieces stay empty rather than failing. */
	static ClanInfo fromJson(JsonObject o)
	{
		ClanInfo c = new ClanInfo();

		if (o == null)
		{
			return c;
		}

		JsonObject points = obj(o, "points");
		c.points = num(points, "total");
		c.monthPoints = num(points, "month");

		long dropMin = num(o, "dropMin");

		if (dropMin > 0)
		{
			c.dropMin = dropMin;
		}

		JsonObject pvm = obj(o, "pvm");
		c.pvmRank = str(pvm, "rank");
		c.pvmGame = str(pvm, "game");
		JsonObject pvmNext = obj(pvm, "next");
		c.pvmNext = str(pvmNext, "name");
		c.pvmLeft = num(pvmNext, "left");
		c.pvmFrom = num(pvm, "from");
		c.pvmAt = num(pvmNext, "at");

		JsonObject loyalty = obj(o, "loyalty");
		c.days = loyalty != null && loyalty.has("days") && !loyalty.get("days").isJsonNull() ? loyalty.get("days").getAsInt() : null;
		c.loyaltyRank = str(loyalty, "rank");
		c.loyaltyGame = str(loyalty, "game");
		JsonObject loyaltyNext = obj(loyalty, "next");
		c.loyaltyNext = str(loyaltyNext, "name");
		c.loyaltyLeft = num(loyaltyNext, "left");
		c.loyaltyFrom = num(loyalty, "from");
		c.loyaltyAt = num(loyaltyNext, "at");

		JsonObject profile = obj(o, "profile");
		JsonObject diaries = obj(profile, "diaries");
		JsonObject tasks = obj(profile, "tasks");
		c.diariesDone = (int) num(diaries, "done");
		c.diariesTotal = (int) num(diaries, "total");
		c.tasksDone = (int) num(tasks, "done");
		c.tasksTotal = (int) num(tasks, "total");

		c.chatIcon = str(o, "chatIcon");
		if (o.has("ranks") && o.get("ranks").isJsonArray())
		{
			for (JsonElement el : o.getAsJsonArray("ranks"))
			{
				JsonObject r = el.getAsJsonObject();
				c.ranks.add(new RankRow(str(r, "group"), str(r, "name"), str(r, "game"), str(r, "how")));
			}
		}

		c.dmUrl = str(o, "dmUrl");

		if (o.has("recent") && o.get("recent").isJsonArray())
		{
			for (JsonElement el : o.getAsJsonArray("recent"))
			{
				JsonObject r = el.getAsJsonObject();
				c.recent.add(new Recent(str(r, "what"), num(r, "points"), num(r, "at"), str(r, "detail"), str(r, "url")));
			}
		}

		c.mismatch = o.has("mismatch") && o.get("mismatch").getAsBoolean();

		if (o.has("accounts") && o.get("accounts").isJsonArray())
		{
			for (JsonElement el : o.getAsJsonArray("accounts"))
			{
				if (el.isJsonPrimitive())
				{
					c.accounts.add(el.getAsString());
				}
			}
		}

		JsonObject links = obj(o, "links");
		c.linkInvite = str(links, "invite");
		c.linkEvents = str(links, "events");
		c.linkAnnouncements = str(links, "announcements");
		c.linkLeaderboard = str(links, "leaderboard");

		if (o.has("pending") && o.get("pending").isJsonArray())
		{
			for (JsonElement el : o.getAsJsonArray("pending"))
			{
				JsonObject p = el.getAsJsonObject();
				c.pending.add(new Pending(str(p, "item"), num(p, "points"), num(p, "full"), num(p, "until")));
			}
		}

		c.staff = o.has("staff") && o.get("staff").getAsBoolean();
		fill(obj(o, "rankIcons"), c.rankIcons);

		JsonObject ladder = obj(o, "ladder");

		if (ladder != null)
		{
			c.inClan = !ladder.has("inClan") || ladder.get("inClan").getAsBoolean();
			c.ladderOn = str(ladder, "on");
			c.ladderPending = str(ladder, "pending");

			if (ladder.has("targets") && ladder.get("targets").isJsonArray())
			{
				for (JsonElement el : ladder.getAsJsonArray("targets"))
				{
					JsonObject t = el.getAsJsonObject();
					c.ladderTargets.add(new Target(str(t, "to"), str(t, "rankName")));
				}
			}
		}

		return c;
	}

	private static void fill(JsonObject from, Map<String, String> into)
	{
		if (from == null)
		{
			return;
		}

		for (Map.Entry<String, JsonElement> e : from.entrySet())
		{
			if (e.getValue().isJsonPrimitive())
			{
				into.put(e.getKey(), e.getValue().getAsString());
			}
		}
	}

	private static JsonObject obj(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);

		return e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
	}

	private static String str(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);

		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}

	private static long num(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);

		return e != null && e.isJsonPrimitive() ? e.getAsLong() : 0;
	}
}

package com.sable;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

/**
 * The one code a member pastes into the settings: the key, a dot, then the bot's address, encoded.
 *
 * It lets the plugin carry no address of its own and the member type none: the clan's bot
 * puts its own address into the code it hands out. Only the key part is ever sent as the
 * credential. A code with no address part, or one that is not an http(s) address, gives
 * an empty address, and then nothing is sent.
 */
final class KeyCode
{
	final String key;
	final String address;

	private KeyCode(String key, String address)
	{
		this.key = key;
		this.address = address;
	}

	/** Splits what was pasted. Never throws; anything unreadable is an empty key and address. */
	static KeyCode parse(String pasted)
	{
		String text = pasted == null ? "" : pasted.trim();
		int dot = text.indexOf('.');

		if (dot < 0)
		{
			return new KeyCode(text, "");
		}

		String key = text.substring(0, dot).trim();
		String address = "";

		try
		{
			String decoded = new String(Base64.getUrlDecoder().decode(text.substring(dot + 1).trim()), StandardCharsets.UTF_8).trim();

			while (decoded.endsWith("/"))
			{
				decoded = decoded.substring(0, decoded.length() - 1);
			}

			if (decoded.toLowerCase().startsWith("http://") || decoded.toLowerCase().startsWith("https://"))
			{
				address = decoded;
			}
		}
		catch (IllegalArgumentException e)
		{
			// Not a code from the clan's bot; no address, so nothing is sent.
		}

		return new KeyCode(key, address);
	}
}

